from lib import *
S = SS('w85')
steps = [
    step("多路复用。10 个请求,每个让服务器“思考”300 ms 再返回 20 KB;本机 netlab 每方向 50 ms(往返 100 ms)。HTTP/1.1 一条连接顺序发:4143 ms(≈ 握手 1 RTT + 10 × (1 RTT + 300 ms) = 4100 ms,几乎完全吻合);HTTP/1.1 开 6 条并行连接:913 ms(10 个请求分两批 6 + 4,每批 1 RTT + 300 ms,加握手 ≈ 900 ms);HTTP/2 一条连接 10 个流同时发:814 ms(含 TCP 握手、TLS 握手)。10 个流完成的时刻(从发出请求起)是 [503 ×7, 603 ×3] ms:7 个流在第一批到达,另外 3 个晚了整整 100 ms(一个 RTT)。我猜这是 TCP 初始拥塞窗口(10 个 MSS ≈ 160 KB)装不下 10 × 20 KB = 200 KB,剩下的要多等一个往返——没有进一步验证。所以 HTTP/2 用一条连接做到了接近 6 条 HTTP/1.1 连接的速度(814 对 913 ms),省下了 5 条连接的开销,但没有达到理想中的 600 ms。", t=tl(S(1)), mark=lidx(S(1), 'HTTP/2 一条连接', 'HTTP/1.1 6 条并行连接'), done=lidx(S(1), 'HTTP/1.1 一条连接顺序发'), b=bars([['HTTP/1.1 一条连接顺序', 4143, '4143 ms'], ['HTTP/1.1 六条并行连接', 913, '913 ms'], ['HTTP/2 一条连接', 814, '814 ms']], 4143, mark=[2], done=[0, 1]), kv=KV([['H1 顺序', '4143 ms ≈ 100 + 10 × 400'], ['H1 6 条并行', '913 ms'], ['H2 单连接 10 流', '814 ms(7 个流 503 ms,3 个 603 ms)']], ['H2 单连接 10 流'])),
    step("流量控制。服务器要发 1 MiB,客户端宣告的初始窗口只有默认的 65535 字节,并且故意不确认(不发 WINDOW_UPDATE):服务器只发了 65535 字节(4 个 DATA 帧)就停了,停了 1.5 秒也不动——发送方被窗口卡住,不是网络问题。随后客户端补发 WINDOW_UPDATE(流和连接各 +1 MiB),服务器马上继续,13 ms 后 1048576 字节全部传完。窗口大小直接决定吞吐:往返 100 ms 时下载 4 MiB,初始窗口 65535 字节需要 13.09 秒(0.32 MB/s);262144 字节 3.37 秒(1.24 MB/s);1 MiB 1.11 秒(3.79 MB/s);4 MiB 0.71 秒(5.93 MB/s)。实测吞吐只有“窗口 ÷ RTT”公式值(0.66 / 2.62 / 10.49 / 41.94 MB/s)的一半左右甚至更低,窗口越大偏差越大;我没有查具体原因(可能是我的客户端发 WINDOW_UPDATE 的时机,也可能是慢启动),所以只能说:窗口小是瓶颈,而公式给出的是上限。", t=tl(S(2)), mark=lidx(S(2), '不确认时', '补发 WINDOW_UPDATE'), done=lidx(S(2), '初始窗口    65535', '初始窗口   262144', '初始窗口  1048576', '初始窗口  4194304'), b=bars([['窗口 65535', 0.32, '0.32 MB/s'], ['窗口 256 KiB', 1.24, '1.24 MB/s'], ['窗口 1 MiB', 3.79, '3.79 MB/s'], ['窗口 4 MiB', 5.93, '5.93 MB/s']], 6, mark=[0], done=[1, 2, 3]), kv=KV([['不确认', '服务器发 65535 字节后停住'], ['补 WINDOW_UPDATE', '13 ms 传完剩下的'], ['窗口 65535 / 4 MiB', '13.09 秒 / 0.71 秒']], ['不确认'])),
    step("HPACK 头部压缩。同一个连接上连续发 10 个头部相同的请求(8 个头部,含一个 200 字节的 Cookie,用 HTTP/1.1 文本写约 398 字节):头部块大小依次是 210、8、8、8、8、8、8、8、8、8 字节。第 1 个要把新头部写出来,同时放进动态表(210 字节);从第 2 个起只写“引用动态表的第几项”,8 字节,压缩到原来的 2.0%。把动态表关掉(HEADER_TABLE_SIZE = 0)后是 211、210、210——每次都得重新写,只剩霍夫曼编码和静态表的压缩。只改一个头部的值(换一个新的 200 字节 Cookie)时,下一个请求的头部块是 160 字节:新 Cookie 要整个重发,其余仍然是引用。对 example.com 同一个连接上连发 3 个请求,响应头部解码后都是 243 字节;这一项我只量了解码后的大小,没有量线上的 HPACK 字节数,所以看不出动态表对响应方向的效果(上一篇看到第一个响应的头部块是 160 字节)。", t=tl(S(3)), mark=lidx(S(3), '10 个相同请求的头部块大小', '第 1 个 210 字节', '把动态表关掉'), done=lidx(S(3), '只改一个头部的值', 'example.com 三次响应'), b=bars([['第 1 个请求', 210, '210 字节'], ['第 2~10 个请求', 8, '8 字节'], ['关掉动态表 每个', 210, '210 字节'], ['只换 Cookie', 160, '160 字节']], 211, mark=[1], done=[0, 2, 3]), kv=KV([['第 1 个', '210 字节(写出来 + 入表)'], ['第 2 个起', '8 字节(只引用,≈ 2.0%)'], ['动态表关掉', '每个 210 字节'], ['换一个 Cookie', '160 字节']], ['第 2 个起'])),
]
